<?php
require_once __DIR__.'/../auth/auth.php';require_once __DIR__.'/../database/db.php';require_once __DIR__.'/../helpers/helpers.php';require_once __DIR__.'/../helpers/stuff.php';$current_page='admin';$admin_tab='inventory';require_admin();
$stmt=$conn->prepare("SELECT p.*,COALESCE(SUM(CASE WHEN o.status='completed' THEN oi.quantity ELSE 0 END),0) units_sold FROM products p LEFT JOIN order_items oi ON oi.product_id=p.id LEFT JOIN orders o ON o.id=oi.order_id GROUP BY p.id ORDER BY p.quantity ASC,p.name");$stmt->execute();$products=$stmt->fetchAll();require __DIR__.'/../includes/header.php';?>
<section class="dashboard-shell"><div class="container"><div class="dashboard-heading"><div><p class="tech-label">// INVENTORY_CONTROL</p><h1 class="section-heading">INVENTORY</h1><p class="dashboard-subtext">Stock levels and automatic sales popularity.</p></div></div><?php require __DIR__.'/../includes/admin-nav.php'; ?><div class="inventory-cards"><?php foreach($products as $p):$q=(int)$p['quantity'];$sold=(int)$p['units_sold'];?><article class="inventory-card"><div><small><?php echo safe_output($p['product_code']); ?></small><h3><?php echo safe_output($p['name']); ?></h3></div><strong><?php echo $q; ?><small> IN STOCK</small></strong><div class="inventory-card-meta"><span><?php echo $sold; ?> SOLD</span><span><?php echo $sold>=POPULAR_THRESHOLD?'POPULAR':'STANDARD'; ?></span><span><?php echo $q===0?'OUT OF STOCK':($q<=5?'LOW STOCK':'NOMINAL'); ?></span></div><a class="text-link compact-link" href="edit-product.php?id=<?php echo (int)$p['id']; ?>">EDIT PRODUCT →</a></article><?php endforeach; ?></div></div></section><?php require __DIR__.'/../includes/footer.php'; ?>
